def transform(grid):
    n = len(grid)

    # The diagonal traces encode a cyclic color sequence. Order the traces
    # from the lower/right end back toward the upper/left end.
    by_color = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                by_color.setdefault(value, []).append((r, c))

    if len(by_color) == 1:
        v = next(iter(by_color))
        return [[v] * n for _ in range(n)]

    # Trace endpoints are the positions farthest along their diagonal.
    traces = []
    for color, pts in by_color.items():
        # In these patterns the markers progress down-left or down-right;
        # the extreme coordinate locates the trace in the overall sequence.
        traces.append((max(r + c for r, c in pts), color))
    traces.sort(reverse=True)
    palette = [color for _, color in traces]

    return [[palette[(r + c) % len(palette)] for c in range(n)]
            for r in range(n)]
